// Pure SCADA Energy & EVN TOU Processor — ZERO Simulated Data
var tsMs = metadata.ts != null ? Long.parseLong(metadata.ts.toString()) : System.currentTimeMillis();
var rawIn = msg.kwh != null ? Double.parseDouble(msg.kwh.toString()) : (msg.kWh != null ? Double.parseDouble(msg.kWh.toString()) : null);
var lastRaw = metadata.ss_last_raw_kwh != null ? Double.parseDouble(metadata.ss_last_raw_kwh.toString()) : null;

var hasLiveReading = (rawIn != null && rawIn > 0.0);
var raw = hasLiveReading ? rawIn : lastRaw;
if (raw == null || raw <= 0.0) {
    return null;
}

// Pure TBEL civil calendar in Vietnam timezone (UTC+7)
var vnMs = tsMs + 25200000L;
var daysEpoch = toInt(vnMs / 86400000L);
var minOfDay = toInt(vnMs / 60000L) % 1440;
var dow = ((daysEpoch + 3) % 7) + 1; // 1 = Monday .. 7 = Sunday

var z = daysEpoch + 719468;
var era = toInt(z / 146097);
var doe = z - era * 146097;
var yoe = toInt((doe - toInt(doe / 1460) + toInt(doe / 36524) - toInt(doe / 146096)) / 365);
var y = yoe + era * 400;
var doy = doe - (365 * yoe + toInt(yoe / 4) - toInt(yoe / 100));
var mp = toInt((5 * doy + 2) / 153);
var dy = doy - toInt((153 * mp + 2) / 5) + 1;
var mo = mp < 10 ? mp + 3 : mp - 9;
var yr = y + (mo <= 2 ? 1 : 0);

// Monday of current week
var monDays = daysEpoch - (dow - 1);
var zm = monDays + 719468;
var eram = toInt(zm / 146097);
var doem = zm - eram * 146097;
var yoem = toInt((doem - toInt(doem / 1460) + toInt(doem / 36524) - toInt(doem / 146096)) / 365);
var ym = yoem + eram * 400;
var doym = doem - (365 * yoem + toInt(yoem / 4) - toInt(yoem / 100));
var mpm = toInt((5 * doym + 2) / 153);
var dym = doym - toInt((153 * mpm + 2) / 5) + 1;
var mom = mpm < 10 ? mpm + 3 : mpm - 9;
var yrm = ym + (mom <= 2 ? 1 : 0);

var curDayId = yr + "-" + (mo < 10 ? "0" + mo : "" + mo) + "-" + (dy < 10 ? "0" + dy : "" + dy);
var curWeekId = yrm + "-" + (mom < 10 ? "0" + mom : "" + mom) + "-" + (dym < 10 ? "0" + dym : "" + dym);
var curMonthId = yr + "-" + (mo < 10 ? "0" + mo : "" + mo);
var curQuarterId = yr + "-Q" + (toInt((mo - 1) / 3) + 1);
var curYearId = "" + yr;

var bDay = metadata.ss_baseline_kwh_day != null ? Double.parseDouble(metadata.ss_baseline_kwh_day.toString()) : raw;
var bWeek = metadata.ss_baseline_kwh_week != null ? Double.parseDouble(metadata.ss_baseline_kwh_week.toString()) : bDay;
var bMonth = metadata.ss_baseline_kwh_month != null ? Double.parseDouble(metadata.ss_baseline_kwh_month.toString()) : bWeek;
var bQuarter = metadata.ss_baseline_kwh_quarter != null ? Double.parseDouble(metadata.ss_baseline_kwh_quarter.toString()) : bMonth;
var bYear = metadata.ss_baseline_kwh_year != null ? Double.parseDouble(metadata.ss_baseline_kwh_year.toString()) : bQuarter;

var kwhYest = metadata.ss_kwh_yesterday != null ? Double.parseDouble(metadata.ss_kwh_yesterday.toString()) : 0.0;

var btDay = metadata.ss_tou_bt_today != null ? Double.parseDouble(metadata.ss_tou_bt_today.toString()) : 0.0;
var cdDay = metadata.ss_tou_cd_today != null ? Double.parseDouble(metadata.ss_tou_cd_today.toString()) : 0.0;
var tdDay = metadata.ss_tou_td_today != null ? Double.parseDouble(metadata.ss_tou_td_today.toString()) : 0.0;

var btWeek = metadata.ss_tou_bt_week != null ? Double.parseDouble(metadata.ss_tou_bt_week.toString()) : 0.0;
var cdWeek = metadata.ss_tou_cd_week != null ? Double.parseDouble(metadata.ss_tou_cd_week.toString()) : 0.0;
var tdWeek = metadata.ss_tou_td_week != null ? Double.parseDouble(metadata.ss_tou_td_week.toString()) : 0.0;

var btMonth = metadata.ss_tou_bt_month != null ? Double.parseDouble(metadata.ss_tou_bt_month.toString()) : 0.0;
var cdMonth = metadata.ss_tou_cd_month != null ? Double.parseDouble(metadata.ss_tou_cd_month.toString()) : 0.0;
var tdMonth = metadata.ss_tou_td_month != null ? Double.parseDouble(metadata.ss_tou_td_month.toString()) : 0.0;

var btQuarter = metadata.ss_tou_bt_quarter != null ? Double.parseDouble(metadata.ss_tou_bt_quarter.toString()) : 0.0;
var cdQuarter = metadata.ss_tou_cd_quarter != null ? Double.parseDouble(metadata.ss_tou_cd_quarter.toString()) : 0.0;
var tdQuarter = metadata.ss_tou_td_quarter != null ? Double.parseDouble(metadata.ss_tou_td_quarter.toString()) : 0.0;

var btYear = metadata.ss_tou_bt_year != null ? Double.parseDouble(metadata.ss_tou_bt_year.toString()) : 0.0;
var cdYear = metadata.ss_tou_cd_year != null ? Double.parseDouble(metadata.ss_tou_cd_year.toString()) : 0.0;
var tdYear = metadata.ss_tou_td_year != null ? Double.parseDouble(metadata.ss_tou_td_year.toString()) : 0.0;

var rolledOver = false;
// Automatic Calendar Rollover checks (executes even if meter is currently OFFLINE so stale periods reset to 0!)
if (metadata.ss_period_day_id == null || !metadata.ss_period_day_id.toString().equals(curDayId)) {
    var prevDayKwh = Math.max(0.0, Math.round((raw - bDay) * 10.0) / 10.0);
    kwhYest = prevDayKwh;
    bDay = raw;
    btDay = 0.0; cdDay = 0.0; tdDay = 0.0;
    rolledOver = true;
}
if (metadata.ss_period_week_id == null || !metadata.ss_period_week_id.toString().equals(curWeekId)) {
    bWeek = raw;
    btWeek = 0.0; cdWeek = 0.0; tdWeek = 0.0;
    rolledOver = true;
}
if (metadata.ss_period_month_id == null || !metadata.ss_period_month_id.toString().equals(curMonthId)) {
    bMonth = raw;
    btMonth = 0.0; cdMonth = 0.0; tdMonth = 0.0;
    rolledOver = true;
}
if (metadata.ss_period_quarter_id == null || !metadata.ss_period_quarter_id.toString().equals(curQuarterId)) {
    bQuarter = raw;
    btQuarter = 0.0; cdQuarter = 0.0; tdQuarter = 0.0;
    rolledOver = true;
}
if (metadata.ss_period_year_id == null || !metadata.ss_period_year_id.toString().equals(curYearId)) {
    bYear = raw;
    btYear = 0.0; cdYear = 0.0; tdYear = 0.0;
    rolledOver = true;
}

// If meter is offline and no rollover happened, do not emit redundant telemetry
if (!hasLiveReading && !rolledOver) {
    return null;
}

var dKwh = (hasLiveReading && lastRaw != null) ? (raw - lastRaw) : 0.0;
if (dKwh < 0.0 || dKwh > 500.0) {
    dKwh = 0.0;
}
dKwh = Math.round(dKwh * 1000.0) / 1000.0;

var tier = "normal";
if (minOfDay >= 1320 || minOfDay < 240) {
    tier = "offpeak";
} else if (dow != 7 && ((minOfDay >= 570 && minOfDay < 690) || (minOfDay >= 1020 && minOfDay < 1200))) {
    tier = "peak";
}

var dNorm = tier == "normal" ? dKwh : 0.0;
var dPeak = tier == "peak" ? dKwh : 0.0;
var dOff = tier == "offpeak" ? dKwh : 0.0;

btDay = Math.round((btDay + dNorm) * 10.0) / 10.0;
cdDay = Math.round((cdDay + dPeak) * 10.0) / 10.0;
tdDay = Math.round((tdDay + dOff) * 10.0) / 10.0;

btWeek = Math.round((btWeek + dNorm) * 10.0) / 10.0;
cdWeek = Math.round((cdWeek + dPeak) * 10.0) / 10.0;
tdWeek = Math.round((tdWeek + dOff) * 10.0) / 10.0;

btMonth = Math.round((btMonth + dNorm) * 10.0) / 10.0;
cdMonth = Math.round((cdMonth + dPeak) * 10.0) / 10.0;
tdMonth = Math.round((tdMonth + dOff) * 10.0) / 10.0;

btQuarter = Math.round((btQuarter + dNorm) * 10.0) / 10.0;
cdQuarter = Math.round((cdQuarter + dPeak) * 10.0) / 10.0;
tdQuarter = Math.round((tdQuarter + dOff) * 10.0) / 10.0;

btYear = Math.round((btYear + dNorm) * 10.0) / 10.0;
cdYear = Math.round((cdYear + dPeak) * 10.0) / 10.0;
tdYear = Math.round((tdYear + dOff) * 10.0) / 10.0;

var kwhToday = Math.max(0.0, Math.round((raw - bDay) * 10.0) / 10.0);
var kwhWeek = Math.max(0.0, Math.round((raw - bWeek) * 10.0) / 10.0);
var kwhMonth = Math.max(0.0, Math.round((raw - bMonth) * 10.0) / 10.0);
var kwhQuarter = Math.max(0.0, Math.round((raw - bQuarter) * 10.0) / 10.0);
var kwhYear = Math.max(0.0, Math.round((raw - bYear) * 10.0) / 10.0);

var outMsg = {
    "last_raw_kwh": raw,
    "evn_tou_tier": tier,
    "period_day_id": curDayId,
    "period_week_id": curWeekId,
    "period_month_id": curMonthId,
    "period_quarter_id": curQuarterId,
    "period_year_id": curYearId,
    "baseline_kwh_day": bDay,
    "baseline_kwh_week": bWeek,
    "baseline_kwh_month": bMonth,
    "baseline_kwh_quarter": bQuarter,
    "baseline_kwh_year": bYear,
    "kwh_yesterday": kwhYest,
    "kwh_today": kwhToday,
    "kwh_week": kwhWeek,
    "kwh_month": kwhMonth,
    "kwh_quarter": kwhQuarter,
    "kwh_year": kwhYear,
    "tou_bt_today": btDay,
    "tou_cd_today": cdDay,
    "tou_td_today": tdDay,
    "tou_bt_week": btWeek,
    "tou_cd_week": cdWeek,
    "tou_td_week": tdWeek,
    "tou_bt_month": btMonth,
    "tou_cd_month": cdMonth,
    "tou_td_month": tdMonth,
    "tou_bt_quarter": btQuarter,
    "tou_cd_quarter": cdQuarter,
    "tou_td_quarter": tdQuarter,
    "tou_bt_year": btYear,
    "tou_cd_year": cdYear,
    "tou_td_year": tdYear
};

if (hasLiveReading) {
    outMsg.last_meter_ts = tsMs;
}
if (dKwh > 0.0) {
    outMsg.delta_kwh = dKwh;
    outMsg.delta_kwh_normal = dNorm;
    outMsg.delta_kwh_peak = dPeak;
    outMsg.delta_kwh_offpeak = dOff;
}

var pTot = msg.p_total != null ? Double.parseDouble(msg.p_total.toString()) : 0.0;
var ratedKw = metadata.ss_rated_kw != null ? Double.parseDouble(metadata.ss_rated_kw.toString()) : 100.0;
outMsg.peak_overload_warning = (hasLiveReading && tier == "peak" && pTot > ratedKw * 0.95);

return {msg: outMsg, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

