// Accumulate runtime hours (life, cycle, cont) for all 16 DI channels on ONSEN_PLC_MAIN
var tsMs = metadata.ts != null ? Long.parseLong(metadata.ts.toString()) : System.currentTimeMillis();
var lastTs = metadata.ss_last_plc_di_ts != null ? Long.parseLong(metadata.ss_last_plc_di_ts.toString()) : tsMs;
var dtHrs = (tsMs - lastTs) / 3600000.0;
if (dtHrs < 0.0 || dtHrs > 24.0) {
    dtHrs = 0.0;
}

var rtMap = {};
if (metadata.ss_di_runtime_map_json != null && !metadata.ss_di_runtime_map_json.toString().isEmpty()) {
    rtMap = JSON.parse(metadata.ss_di_runtime_map_json.toString());
}

var diKeys = [
    "DI_01_X0", "DI_02_X1", "DI_03_X2", "DI_04_X3",
    "DI_05_X4", "DI_06_X5", "DI_07_X6", "DI_08_X7",
    "DI_09_X10", "DI_10_X11", "DI_11_X12", "DI_12_X13",
    "DI_13_X14", "DI_14_X15", "DI_15_X16", "DI_16_X17"
];

var hasAnyDi = false;
var maskVal = msg.DI_BITMASK_16 != null ? Integer.parseInt(msg.DI_BITMASK_16.toString()) : -1;

for (var i = 0; i < diKeys.size(); i++) {
    var k = diKeys[i];
    var vObj = msg[k];
    var isOn = false;
    var hasCh = false;
    if (vObj != null) {
        hasCh = true;
        var s = vObj.toString().trim().toUpperCase();
        isOn = (s.equals("1") || s.equals("1.0") || s.equals("TRUE") || s.equals("ON") || s.equals("RUNNING"));
    } else if (maskVal >= 0) {
        hasCh = true;
        isOn = ((maskVal & (1 << i)) != 0);
    }

    if (hasCh) {
        hasAnyDi = true;
        var entry = rtMap[k];
        if (entry == null) {
            entry = {
                "ch": i,
                "diKey": k,
                "life": 0.0,
                "cycle": 0.0,
                "cont": 0.0,
                "limit": 1000.0,
                "lastDate": "01/10/2026 08:00",
                "resetCount": 1
            };
        }
        var life = entry.life != null ? Double.parseDouble(entry.life.toString()) : 0.0;
        var cycle = entry.cycle != null ? Double.parseDouble(entry.cycle.toString()) : 0.0;
        var cont = entry.cont != null ? Double.parseDouble(entry.cont.toString()) : 0.0;

        if (isOn) {
            life = Math.round((life + dtHrs) * 100.0) / 100.0;
            cycle = Math.round((cycle + dtHrs) * 100.0) / 100.0;
            cont = Math.round((cont + dtHrs) * 100.0) / 100.0;
        } else {
            cont = 0.0;
        }
        entry.life = life;
        entry.cycle = cycle;
        entry.cont = cont;
        entry.running = isOn ? 1 : 0;
        rtMap[k] = entry;
    }
}

if (!hasAnyDi) {
    return null;
}

var outMsg = {
    "last_plc_di_ts": tsMs,
    "di_runtime_map_json": JSON.stringify(rtMap)
};
return {msg: outMsg, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

