// Pre-process & normalize incoming telemetry from AMI-Gateway (20 Live Devices)
msg.remove("m3Air");
msg.remove("m3LPG");
msg.remove("delta_CO2");
msg.remove("sourceTs");
msg.remove("source_ts");

var devName = metadata.deviceName != null ? metadata.deviceName.toString() : "";
var devType = metadata.deviceType != null ? metadata.deviceType.toString() : "";

if (devName.startsWith("54A_")) {
    return null;
}

// Strip PLC_Heartbeat from slave devices (TK4S & ADL400) so it never pollutes ts_kv
if (!devName.equals("ONSEN_PLC_MAIN")) {
    msg.remove("PLC_Heartbeat");
}

// Map 3-phase power keys on Acrel ADL400 meters
if (msg.Power_Active_A != null && msg.p_a == null) { msg.p_a = msg.Power_Active_A; }
if (msg.Power_Active_B != null && msg.p_b == null) { msg.p_b = msg.Power_Active_B; }
if (msg.Power_Active_C != null && msg.p_c == null) { msg.p_c = msg.Power_Active_C; }
if (msg.v_a != null && msg.u_a == null) { msg.u_a = msg.v_a; }
if (msg.v_b != null && msg.u_b == null) { msg.u_b = msg.v_b; }
if (msg.v_c != null && msg.u_c == null) { msg.u_c = msg.v_c; }

var qStr = msg.quality != null ? msg.quality.toString().trim().toUpperCase() : "";
var errStr = msg.errorReason != null ? msg.errorReason.toString().trim() : "";
var hcStr = msg.health_chain_code != null ? msg.health_chain_code.toString().trim() : "";
if (errStr.isEmpty() && !hcStr.isEmpty() && !hcStr.equals("OK")) {
    errStr = hcStr;
}

var isChainBad = false;
if (msg.gw_tcp_ok != null && (msg.gw_tcp_ok.toString().equals("0") || msg.gw_tcp_ok.toString().equals("false"))) { isChainBad = true; }
if (msg.plc_run_ok != null && (msg.plc_run_ok.toString().equals("0") || msg.plc_run_ok.toString().equals("false"))) { isChainBad = true; }
if (msg.rs485_comm_ok != null && (msg.rs485_comm_ok.toString().equals("0") || msg.rs485_comm_ok.toString().equals("false"))) { isChainBad = true; }
if (msg.Comm_OK != null && (msg.Comm_OK.toString().equals("0") || msg.Comm_OK.toString().equals("false"))) { isChainBad = true; }

if (qStr.equals("BAD") || isChainBad) {
    msg.quality = "BAD";
    msg.comm_status = "OFFLINE";
    msg.online = 0;
    msg.errorReason = errStr.isEmpty() ? "MODBUS_PLC_OFFLINE" : errStr;
} else {
    msg.quality = "GOOD";
    msg.comm_status = "ONLINE";
    msg.online = 1;
    msg.errorReason = "";
}

return {msg: msg, metadata: metadata, msgType: msgType};

