configuration.jsScript:
// Route demultiplexed Zone Asset message
var qStr = msg.quality != null ? msg.quality.toString().toUpperCase() : "";
if (qStr.equals("BAD")) {
    if (msg.comm_status != null && msg.comm_status.toString().equals("SENSOR_FAULT")) {
        return ["Zone_Status_Route", "Sensor_Spike_Fault"];
    }
    return ["Comm_Fault_Route"];
}

var routes = ["Zone_Status_Route", "Comm_Restored_Route"];
if (msg.temperature != null) {
    var t = Double.parseDouble(msg.temperature.toString());
    if (t < -45.0 || t > 160.0) {
        msg.quality = "BAD";
        msg.comm_status = "SENSOR_FAULT";
        msg.errorReason = "PT100_WIRE_FAULT:" + t + "C";
        return ["Zone_Status_Route", "Sensor_Spike_Fault"];
    }
    routes.add("Zone_Temp_TS_Route");
    routes.add("Temp_Route");
}
return routes;

